  write('yolo-loss',3,'CIoU：两个框不重叠时还比较什么',[
    'CIoU是Complete Intersection over Union（完全交并比），是一种框相似度度量：除重叠外，还比较中心距离与宽高比；训练中常把1−CIoU用作定位损失。因此即使两框不重叠，也能保留部分几何差异信号。下面先固定相同宽高，单独看中心距离项；并非重新定义普通IoU。 固定真实框与预测框宽高均为2，真实中心(0,0)，预测中心(4,0)。两框不重叠，IoU=0。中心距离平方为4²=16；包住两框的最小外接矩形宽6、高2，对角线平方为6²+2²=40。',
    '两框长宽比相同，因此本例比例惩罚为0，CIoU=IoU−16/40=−0.4，框损失1−CIoU=1.4。CIoU包含中心距离与长宽比信息，可小于0；这个1.4并不表示损失函数算错。',
    '物体性目标另取max(CIoU,0)，本例为0，并detach目标支路；框项仍为1.4。截断物体性目标不会把框损失也截成0。代码变量名iou在这里实际保存了CIoU结果，阅读时看计算函数的CIoU=True参数。'
  ],{advancedBlocks:[advanced('选读：完整CIoU公式','\\[\\operatorname{CIoU}=\\operatorname{IoU}-\\frac{\\rho^2}{c^2}-\\alpha v,\\qquad v=\\frac{4}{\\pi^2}\\left(\\arctan\\frac{w_t}{h_t}-\\arctan\\frac{w_p}{h_p}\\right)^2.\\]ρ²为两框中心距离平方，c²为最小外接矩形对角线平方；w/h分别为真实t与预测p框宽高。v衡量宽高比例差，α通常按v/(1−IoU+v+ε)构造，ε防止除0；当前实现对α的计算停止梯度。','本节相同比例令v=0，故可直接算−16/40。其他形状要保留长宽比项及具体实现中的数值稳定处理。')]});

  write('train-yolo',0,'把命令里的每一项对应到实际文件和预算',[
    '训练是用带标注的图片反复调整模型参数，让框位置与类别等预测更符合参考答案的过程。训练命令除了选择模型，还规定数据来源、输入大小和训练预算；这些设置会改变实际学习过程。本课先做短程运行，验证数据和更新流程确实走通，再扩大训练。 第一次运行先做一轮检查。准备好已安装依赖的YOLOv5项目、真实图片与标签、指向它们的数据配置，以及可用的初始化权重。在终端进入能看到train.py的项目最外层文件夹，这个位置叫仓库根目录。终端是输入运行命令的窗口；下方命令应输在那里，标签文件里只写目标记录。',
    '读命令可以从左到右：python表示让Python运行后面的train.py；每个以--开头的名字是一个选项，它后面的内容是这次给它的值。例如--epochs 1就是先遍历训练集一轮，--data后面的文件告诉程序去哪里取图片。出现路径错误时先检查终端所在位置及文件是否存在。',
    '--data指出图片地址与类别表；--cfg描述模型结构；--weights提供初始化参数；--imgsz规定训练尺度；--batch-size决定一批几张图；--epochs是将训练集合重复遍历的轮数。数据表一轮有100张、batch=4且无分布式/特殊采样时，通常有25个batch。',
    '本地训练脚本改过默认数据路径，应显式传data参数。Windows若读取多进程报错，可先用--workers 0把加载改为当前进程处理，定位清楚后再考虑吞吐。实际保存目录以日志为准，重复实验名可能被自动递增。'
  ],{learningFigure:'command'});
  write('train-yolo',1,'日志中的训练损失、验证指标和权重各指什么',[
    'box_loss记录框的位置误差，obj_loss记录物体性误差，cls_loss记录类别误差；它们是训练目标，不是准确率。epoch表示完成的训练轮数。验证中的P（精确率）是报告出的预测中正确的比例，R（召回率）是真实目标中被找到的比例，AP汇总不同分数位置的精确率与召回率。先分清它们的职责，再比较同一实验的变化。',
    '例如某轮box从0.04降0.03，但验证AP50:95（按IoU 0.50到0.95等多个定位门槛汇总的AP）从0.45降0.42，意味着训练定位目标更易满足，验证检测表现却下降。这个假设日志不能单独证明过拟合；还需回看划分、增强、标签与分组错误。',
    'last.pt保存最近一次已保存轮次，best.pt按验证fitness选择。正常结束会清理这些最终权重中的优化器状态等字段，因此文件名last并不保证仍能完整续训。出现NaN（无效数值）或Inf（无穷大）时，先定位哪一步首次出现，再查输入、损失和精度。'
  ],{advancedBlocks:[advanced('选读：别把其他模型的日志列搬过来','当前标准Anchor-based YOLOv5 ComputeLoss是box、obj、cls三项。其他模型可能出现DFL（Distribution Focal Loss，分布焦点损失），用于离散分布形式的框距离监督；它不是这里新增的第四项，也不是物体性损失的另一种名字。')]});
  write('train-yolo',2,'先证明管线走通，再扩大实验',[
    '第一步取少量已人工核对的图片，查看训练批次图中的框与类别；第二步短跑1～3轮，确认输入有限、三项损失有记录、验证能读取正确数据；第三步才增加预算。短跑测的是流程，不足以断言模型已能用于现场。',
    '若想判断能否拟合，另建几张图的小实验并减弱复杂增强，看训练目标能否持续下降。若连这些图也不能拟合，优先查标签、参数是否参与优化、梯度和学习率；能拟合后，再用独立验证数据判断推广能力。',
    '记录图片数、输入尺寸、batch、累积设置、轮数与实际耗时。显存不足可以先减batch；目标细节不足可尝试更大输入，但需同时核对显存、速度及小目标验证结果。每次留下一个可对照的基线。'
  ]);
  write('train-yolo',3,'一个batch、一次更新和一轮训练分别发生什么',[
    'DataLoader是把图片与标签组织成一批数据的读取器。模型接收归一化图像，输出三尺度raw；ComputeLoss用targets分配监督；backward计算梯度，optimizer.step才改变参数。batch是一次取图，epoch是走完一轮集合，二者都不必等于参数更新次数。',
    '用固定累积2批的小算例：参数w=1，第1批产生梯度2，先存下；第2批再产生梯度3，累加成5，学习率0.1时执行w=1−0.1×5=0.5，再清空梯度。本例没有额外平均，真实训练应沿损失归约和缩放规则核对，不能自行再除一次累积数。',
    '源码还使用AMP（Automatic Mixed Precision，自动混合精度）：部分计算用较低精度，GradScaler先缩放损失以帮助梯度数值处理，更新前再按其规则处理。梯度裁剪限制过大的梯度；EMA（指数滑动平均）维护参数的平滑副本。先分清职责，再跟代码调用。',
    '默认每轮结束运行验证、计算fitness并按选项保存检查点。普通评估使用eval模式与关闭求导；eval切换BN/Dropout行为，关闭求导则避免构建反传图。正常结束后清理最终权重，恢复中断训练所需状态与部署参数文件应分别保存。'
  ],{learningFigure:'accumulate'});
  write('yolo-checkpoints',0,'把结构、模型参数和训练状态分成三份看',[
    '结构规定有哪些层、怎样相连，模型YAML是它的描述；模型参数是卷积权重等学到的数；训练检查点还可能保存优化器动量、轮次、最佳评分与EMA等状态。能做推理只需完整可用的模型参数及运行配置，接续原实验则需要更多状态。',
    '80类头的P3权重形状是[255,256,1,1]，新2类需要[21,256,1,1]，不能整块复制。本地train.py先建新头，再用intersect_dicts筛选名称与形状兼容的参数。strict=False允许缺少/额外键，并不自动忽略同名形状不匹配。',
    '即使两边都是2类，原顺序[猫,狗]与新顺序[烟雾,火焰]也没有相同语义；层号重排后相同键名也可能承担不同职责。加载日志、模型摘要和类别表需一起核对，不能只看“Transferred”数量大就认定正确。'
  ],{learningFigure:'checkpoint'});
  write('yolo-checkpoints',1,'新任务初始化，与恢复中断实验',[
    '预训练权重提供一个已学过的参数起点；微调是在新数据上继续调整它们；断点续训则恢复中断的同一个训练实验。EMA（Exponential Moving Average，指数移动平均）是用历史参数的平滑平均维护一份模型参数，本版YOLOv5训练还会保存它。只加载一组权重，通常不足以恢复全部训练状态。 新任务微调用--weights指定初始权重，重新开始一次训练安排，可以换数据类别；中断续训用--resume指定保留训练状态的检查点，目标是接上同一个实验的轮次、优化器和EMA等信息。二者即使都读取.pt，也不是同一操作。',
    '假设第12轮保存后，第13轮中途断电，最近完整检查点只能从已保存轮次之后继续；中途尚未保存的batch不能恢复。实际start_epoch按检查点内记录计算，具体轮次从0还是1显示也要看日志。',
    '正常完成后，strip_optimizer可能把epoch改−1、去掉优化器等状态。这样的last.pt可作为新训练的权重起点，但不能承诺完整恢复原中断状态。需要恢复时另存未清理检查点、原配置和数据版本。'
  ]);

  write('yolo-augment',0,'四份设置各自管什么',[
    '一个YOLO实验通常由四处设置共同决定：data YAML给图片位置与类别；model YAML给层连接和规模；hyp YAML给学习率、损失gain与增强幅度/概率；命令行选择这些文件，并设置输入尺寸、batch和训练轮数。文件名写着fire，只是名字，不会自动保证内容适合火焰任务。',
    '数据增强是在训练时按规则改变图片，让模型看到同一内容的不同样子。以一张宽100的火焰图片为例，水平翻转后，框中心x=20要改成x=80；图片变了而标签不变，就给模型错答案。',
    '增强后的样子仍应符合任务。颜色改得过头可能让火焰失去原本线索，裁剪后只剩无法判断的小块也可能引入问题。这里先用可视图核对“图片变了什么，框怎样跟着变”，再讨论参数大小和训练效果。',
    '把最终命令、程序实际采用的配置副本和源码版本一起保存。某个选项可能在命令行覆盖默认值，训练入口又可能按类别数或检测尺度调整gain。比较时看实际运行值，不只看配置文件中的一行。'
  ],{learningFigure:'settings',subheadings:{0:'先认清四份实验设置',1:'增强要同步改变图片和框'}});
  write('yolo-augment',1,'Mosaic先拼图，再同步处理框',[
    'Mosaic常从四次取样的图片构成大画布，各图的框先跟随缩放和平移进入画布，再经后续几何变换与裁剪。一次训练样本因此可能包含多个来源；取样可以重复，不保证四张必然不同。它改变的是样本构造，不是让一张图的类别编号变成四倍。',
    '框必须跟着每次变换走：先变角点、与裁剪边界求交，再按可见框尺寸等规则过滤。若只拼图片而沿用原标签，就会训练到错误位置。HSV改变色调/饱和度/明度，是否允许大幅改色需看类别是否依赖颜色。',
    '当前固定版本不能直接假定具有其他实现的“最后若干轮自动关闭Mosaic”策略。若采用这种安排，查实际训练循环或加载器何时改开关，并记录改了哪些代码；有同名参数也要查它是否真的被调用。'
  ]);
  write('yolo-augment',2,'输入尺寸、每批张数与更新数要一起算',[
    '标准三尺度、每格3个Anchor时，640输入有25,200个候选；960输入三网格为120/60/30，候选数56,700，是2.25倍。这来自空间面积增大，不代表整网延迟或峰值显存也必定是2.25倍。',
    'batch=4是一次4张，累积4批时一次更新可汇合16张的梯度；它在某些条件下帮助控制每次加载的内存，但BN仍逐小批次统计，不能直接当作batch=16在所有方面完全等价。',
    '公平比较需说明固定什么预算：相同轮数、相同优化器更新数、还是相同训练时间。若改batch导致每轮batch数和累积步数变化，记录实际更新次数与学习率安排，避免把训练量变化全归因于输入大小。'
  ],{learningFigure:'budget'});
  write('yolo-augment',3,'把一次增强实验写成可比较的两行',[
    '先固定数据划分、初始化权重、输入尺度、训练预算和评估器，A使用基线增强，B只改Mosaic概率。记录实际配置值、各类AP、夜间误报、耗时与代表性失败图。若同时换模型与输入尺寸，已经不再是只测Mosaic的影响。',
    '若B总体AP上升但烟雾类下降，要回看烟雾目标是否在拼接后过小或被裁碎。根据目标可见尺寸或场景规则调整，再单独比较；不要只保留有利指标。多次随机重复可帮助判断小差距是否稳定。'
  ]);

  write('yolo-evaluation',0,'先匹配位置，再按分数统计表现',[
    '假设验证图里人标了2处火焰，模型最后报告3个火焰框：2个分别找到这2处目标，另1个是重复报告。在每个真实目标只算一次的规则下，找对的2个叫真阳性TP（True Positive）；多报的1个叫假阳性FP（False Positive，误报）；没有漏掉目标，所以假阴性FN（False Negative，漏检）为0。',
    '精确率Precision问“报告的3个里，几个是对的”，本例为2÷3≈66.7%；召回率Recall问“真实2个里，找到了几个”，为2÷2=100%。P和R分别是它们的缩写。若只看“总共报了3个”，无法知道是找全了还是多报了。',
    '怎样判断“框找对了”？先要求类别相同，再比较预测框与真实框覆盖的范围。IoU全称Intersection over Union，中文是交并比：重叠面积÷两个框合起来的面积。例如两个面积各100的框重叠60，合起来100+100−60=140，IoU=60/140≈0.429。完全重合时为1，不相交时为0。',
    '设最低IoU要求为0.5，则上面的0.429不通过。完整验证先在保留的数据上预测，再与标注做一对一匹配；同一真实目标至多匹配一条预测。验证不执行优化器更新。AP还要综合不同分数筛选条件下的表现，后面再说明，不能把这里一次计数的精确率直接叫AP。',
    '再看分数门槛。固定一组已完成NMS的预测，真实目标共2个：A分数0.9，找到第1个；B分数0.8，是一处误报；C分数0.4，找到第2个。A与C对应不同目标，不存在匹配争抢。只改变“分数严格大于门槛才保留”的条件，重新计数如下。',
    '门槛0.85只留下A，精确率100%、召回率50%；降到0.6，多留下误报B，变成50%、50%；再降到0.3，找回C，变成约66.7%、100%。精确率随门槛变化可能起伏。若分数在这组数据上排得不理想，更高门槛也可能把真目标先删掉，不能保证精确率一定更高。',
    '这张表固定了预测框和匹配关系，只研究分数过滤。完整流程若重新运行NMS、改变候选上限或匹配规则，需要按新结果再数；真实数据里没有预测时，精确率分母为0，计算与显示约定应说明。比较模型时同时固定数据、后处理和评价协议。',
    '当前val.py的process_batch先计算预测与标签的IoU、检查类别，再按源码的排序与去重步骤选出一对一配对；AP统计在之后把预测按置信度排序。匹配冲突处理与PR置信度排序是两件事，不要用一份简化课堂规则替代所有评估器。',
    'IoU=0.7的正确类别框在AP50可以匹配，在AP75不通过；因此同一预测在10个IoU阈值下有10个真假标记。需要比较哪个环节变好时，既看AP50，也看更严格定位要求下的结果。'
  ],{learningFigure:'evaluation'});
  write('yolo-evaluation',1,'手算best评分，再核对AP实现',[
    '先拆开指标名字。AP是Average Precision（平均精确率）：固定一个类别和一种定位要求，再综合不同分数筛选位置的精确率—召回率表现，按规定插值和汇总。这里的“平均”不表示随手平均几个精确率。mAP中的m是mean，表示再对纳入评价的类别取平均。',
    'AP50中的50表示匹配框时要求IoU至少0.50，不表示正确率50%。若烟雾的AP50为0.8、火焰为0.4，只有这两个被评价的类别，则mAP50=(0.8+0.4)/2=0.6。这里假定每类AP已经按完整协议算好，不能用某个门槛下的精确率直接代替。',
    'AP50:95进一步使用0.50、0.55、0.60、0.65、0.70、0.75、0.80、0.85、0.90、0.95这10个IoU要求。每个类别在各要求下分别算AP，再按相应协议平均。更大的IoU要求更看重框是否贴近真实边界；这10个数是定位门槛，不是10个分数门槛。日志中mAP50-95就是这种跨类别、跨定位要求的汇总。',
    'fitness是在本实现中挑选best权重的综合评分。假设模型A的mAP50=0.80、mAP50:95=0.40；B分别为0.75和0.45。默认算A=0.1×0.80+0.9×0.40=0.44，B=0.1×0.75+0.9×0.45=0.48，所以按这条规则B得分更高。best不是由最低训练loss或最高mAP50单独决定。',
    'AP先看某类按分数排序的Precision/Recall曲线，再按规定插值和汇总；mAP再跨类别/指定IoU阈值平均。本站CV课已逐行演算PR。本地utils/metrics.py::compute_ap加入端点、求单调精确率包络，在101个召回位置插值，再做梯形积分。',
    'COCO官方评估器按规定召回采样与其他规则汇总，其匹配、忽略区域、目标上限等也有完整约定。YOLO代码中的“101-point”注释不能证明两套结果对任意数据完全相同。报告时写明val.py内部统计还是pycocotools结果及数据版本。'
  ],{learningFigure:'fitness',subheadings:{0:'先读懂AP与mAP的名字',3:'再看best文件按什么规则选',4:'最后核对评价实现'},advancedBlocks:[advanced('选读：日志P/R与实际部署门槛','当前ap_per_class可在平滑后的平均F1曲线上选择读出P/R的位置；这不等于detect.py默认置信度门槛，也不等于每类分别选出的最优生产门槛。部署阈值应在独立验证场景按可接受误报/漏检选择，并在测试或新现场数据检验。')]});
